//! `BSShader/run_00be2290` (Xbox PDB source unit), subsystem `BSShader`: its functions in
//! FalloutNV.exe 1.4.0.525, translated (docs/ENGINE_CRATE.md).
//!
//! The 24 functions here fill the shader system's static passes (the pass slots at
//! `011fdff8..011febd4`): each holds one pass after another in a pass pointer on its stack,
//! gives it texture stages, shader programs and render states, and writes words into the
//! shaders' tables. Each is one long straight run of the same few pieces, so each is a
//! step table ([`Step`]) read from the listing and run by [`run_setup`].

#[allow(unused_imports)]
use crate::prelude::*;
use crate::units::bsshader::geometrydecalshader::shader_inline::{
    ni_pointer_assign, pass_pointer_clear, pass_render_state, stage_release, CREATE_NEW_STAGE,
    PASS_DELETE_00E80190, PASS_SET_STAGE, SETUP_DEFAULT_STAGE, SET_FILTER_MODE,
};
use Step::*;
use Word::*;

/// The pass pointer assignment `00ba53c0` (unnamed, `thiscall` on a pass pointer, the address
/// of another), the stage call `00e7de90` (unnamed, `thiscall` on a stage, one word), and the
/// two pass member setters `00b80600` (the pointer at +0x44) and `00b79950` (the pointer at
/// +0x5c) (unnamed, `thiscall` on the pass, the new pointer).
const PASS_POINTER_ASSIGN_00BA53C0: u32 = 0x00ba_53c0;
const STAGE_CALL_00E7DE90: u32 = 0x00e7_de90;
const SET_PASS_44_00B80600: u32 = 0x00b8_0600;
const SET_PASS_5C_00B79950: u32 = 0x00b7_9950;

/// The set-ups' stack words (a zeroed block): the stage pointer `CreateNewStage` fills, and
/// the pass pointer.
const STAGE_POINTER: u32 = 0;
const PASS_POINTER: u32 = 4;

/// A word a step passes on.
#[derive(Clone, Copy, Debug)]
enum Word {
    /// The word itself.
    Constant(u32),
    /// The word at a global, read when the step runs.
    Global(u32),
    /// A float global loaded and stored by the x87 unit (`FLD`/`FSTP`): its bits, a
    /// signalling NaN made quiet.
    Float(u32),
    /// The index of the [`Step::Repeat`] around the step.
    Index,
    /// The held pass's word at +0x14 (its stage count `SetStage` is given).
    StageCount,
    /// The word at the second global when the byte at the first is not 0, else the word at
    /// the third.
    FlagChosen(u32, u32, u32),
    /// When the word at the first global equals the second word: the word at the fourth
    /// global plus 8 times the word at the third; else the word at the fourth global.
    ModeChosen(u32, u32, u32, u32),
}

/// One piece of a set-up, in the listing's order.
#[derive(Debug)]
enum Step {
    /// The pass at a global held (the pass pointer was 0): its count at +0x64 goes up when it
    /// is not null.
    Acquire(u32),
    /// Another pass held, inline: when the pass at the global is not the held one, the held
    /// pass's count at +0x64 goes down (`00e80190` deletes it at 0, with no null check), the
    /// global is read again into the pass pointer and its count goes up when not null.
    Switch(u32),
    /// Another pass held through `00ba53c0` on the pass pointer with the global's address.
    SwitchThrough(u32),
    /// The held pass given up: its count at +0x64 goes down (no null check), `00e80190`
    /// deleting it at 0.
    Release,
    /// The pass at a global given up and the global cleared, when it is not null.
    ClearPass(u32),
    /// The steps run when the held pass's word at +0x18 is below the number (unsigned).
    StagesBelow(u32, &'static [Step]),
    /// The steps run for each index below the number.
    Repeat(u32, &'static [Step]),
    /// `CreateNewStage` on the stage pointer.
    NewStage,
    /// `SetupDefaultStage` on the stage: the index word and three words.
    DefaultStage(Word, u32, u32, u32),
    /// `NiD3DPass::SetStage` on the held pass: the index word and the stage.
    SetStage(Word),
    /// A word of the stage at the offset set.
    StageWord(u32, Word),
    /// `00e7de90` on the stage with the word.
    StageCall(u32),
    /// `SetFilterMode` on the held pass's stage (its stage array at +0x24, the entry at the
    /// offset): the first of the two values when the word at the global is one of the two
    /// modes, else the second.
    StageFilter(u32, u32, [u32; 2], [u32; 2]),
    /// The held pass's `NiPointer` at the offset set to the object at the global.
    Assign(u32, u32),
    /// `00b80600` on the held pass with the word.
    AssignPixelThrough(Word),
    /// `00b79950` on the held pass with the word.
    AssignVertexThrough(Word),
    /// A render state of the held pass (its block made when missing), the third word 1.
    State(u32, Word),
    /// A word stored at a global.
    Store(u32, u32),
    /// The stage pointer's stage released (its count at +0x60 down, deleted at 0).
    ReleaseStage,
}

/// The word a step passes on, with the stack block and the loop index.
fn word(e: &Engine, frame: u32, index: u32, word: Word) -> u32 {
    match word {
        Constant(value) => value,
        Global(global) => e.global::<u32>(global),
        Float(global) => x87_quiet_bits(e.global::<u32>(global)),
        Index => index,
        StageCount => {
            let pass = e.mem.u32(frame + PASS_POINTER);
            e.mem.u32(pass + 0x14)
        }
        FlagChosen(flag, set, clear) => {
            if e.global::<u8>(flag) != 0 {
                e.global::<u32>(set)
            } else {
                e.global::<u32>(clear)
            }
        }
        ModeChosen(mode, value, position, table) => {
            if e.global::<u32>(mode) == value {
                let position = e.global::<u32>(position);
                e.mem.u32(table.wrapping_add(position.wrapping_mul(8)))
            } else {
                e.global::<u32>(table)
            }
        }
    }
}

/// The held pass's count at +0x64 down by one, `00e80190` deleting it at 0.
fn give_up_pass(e: &mut Engine, pass: u32) {
    let left = e.mem.u32(pass + 0x64).wrapping_sub(1);
    e.mem.set_u32(pass + 0x64, left);
    if left == 0 {
        e.call(PASS_DELETE_00E80190, &args![pass]);
    }
}

/// A pass's count at +0x64 up by one when it is not null.
fn hold_pass(e: &mut Engine, pass: u32) {
    if pass != 0 {
        let count = e.mem.u32(pass + 0x64).wrapping_add(1);
        e.mem.set_u32(pass + 0x64, count);
    }
}

/// Runs the steps with the stack block and the loop index.
fn run_steps(e: &mut Engine, frame: u32, index: u32, steps: &[Step]) {
    for step in steps {
        let pass = e.mem.u32(frame + PASS_POINTER);
        let stage = e.mem.u32(frame + STAGE_POINTER);
        match *step {
            Acquire(global) => {
                let next = e.global::<u32>(global);
                e.mem.set_u32(frame + PASS_POINTER, next);
                hold_pass(e, next);
            }
            Switch(global) => {
                if pass != e.global::<u32>(global) {
                    give_up_pass(e, pass);
                    let next = e.global::<u32>(global);
                    e.mem.set_u32(frame + PASS_POINTER, next);
                    hold_pass(e, next);
                }
            }
            SwitchThrough(global) => {
                e.call(
                    PASS_POINTER_ASSIGN_00BA53C0,
                    &args![frame + PASS_POINTER, global],
                );
            }
            Release => give_up_pass(e, pass),
            ClearPass(global) => pass_pointer_clear(e, global),
            StagesBelow(count, inner) => {
                if e.mem.u32(pass + 0x18) < count {
                    run_steps(e, frame, index, inner);
                }
            }
            Repeat(count, inner) => {
                for each in 0..count {
                    run_steps(e, frame, each, inner);
                }
            }
            NewStage => {
                e.call(CREATE_NEW_STAGE, &args![frame + STAGE_POINTER]);
            }
            DefaultStage(which, first, second, third) => {
                let which = word(e, frame, index, which);
                e.call(
                    SETUP_DEFAULT_STAGE,
                    &args![stage, which, first, second, third],
                );
            }
            SetStage(which) => {
                let which = word(e, frame, index, which);
                e.call(PASS_SET_STAGE, &args![pass, which, stage]);
            }
            StageWord(offset, value) => {
                let value = word(e, frame, index, value);
                e.mem.set_u32(stage + offset, value);
            }
            StageCall(value) => {
                e.call(STAGE_CALL_00E7DE90, &args![stage, value]);
            }
            StageFilter(offset, mode, modes, values) => {
                let current = e.global::<u32>(mode);
                let value = if modes.contains(&current) {
                    values[0]
                } else {
                    values[1]
                };
                let target = e.mem.u32(e.mem.u32(pass + 0x24) + offset);
                e.call(SET_FILTER_MODE, &args![target, value]);
            }
            Assign(offset, global) => {
                let object = e.global::<u32>(global);
                ni_pointer_assign(e, pass + offset, object);
            }
            AssignPixelThrough(value) => {
                let value = word(e, frame, index, value);
                e.call(SET_PASS_44_00B80600, &args![pass, value]);
            }
            AssignVertexThrough(value) => {
                let value = word(e, frame, index, value);
                e.call(SET_PASS_5C_00B79950, &args![pass, value]);
            }
            State(state, value) => {
                let value = word(e, frame, index, value);
                pass_render_state(e, pass, state, value);
            }
            Store(global, value) => e.set_global(global, value),
            ReleaseStage => stage_release(e, stage),
        }
    }
}

/// Runs a set-up's steps on a zeroed stack block (the stage pointer and the pass pointer).
fn run_setup(e: &mut Engine, steps: &[Step]) {
    e.with_stack(8, |e, frame| run_steps(e, frame.addr(), 0, steps));
}

