    /// The (state, value) pairs set on a pass's render-state block, in order.
    fn states_of(e: &Engine, pass: u32) -> Vec<(u32, u32)> {
        let block = e.mem.u32(pass + 0x30);
        calls(e, SET_RENDER_STATE_00E7F430)
            .iter()
            .filter(|a| a[0] == block)
            .map(|a| (a[1], a[2]))
            .collect()
    }

    #[test]
    fn fn_00c01c20_sets_both_passes_as_the_listing_does() {
        let mut e = setup_rig(STEPS_00C01C20);
        fn_00c01c20(&mut e);
        let quiet = 0x7fc0_0001;
        let expected = vec![
            (0x1b, 0),
            (0xf, 0),
            (7, 1),
            (0x17, 4),
            (0xe, 1),
            (0xc3, quiet),
            (0x16, 1),
        ];
        let first = e.global::<u32>(0x011f_e7a0);
        let second = e.global::<u32>(0x011f_e7a4);
        assert_eq!(states_of(&e, first), expected);
        assert_eq!(states_of(&e, second), expected);
        assert_eq!(e.mem.u32(first + 0x5c), e.global::<u32>(0x011f_df8c));
        assert_eq!(e.mem.u32(second + 0x5c), e.global::<u32>(0x011f_df90));
        let pixel = e.global::<u32>(0x011f_dc44);
        assert_eq!(e.mem.u32(first + 0x44), pixel);
        assert_eq!(e.mem.u32(second + 0x44), pixel);
        assert_eq!(e.mem.u32(pixel + 4), 3);
        assert_eq!(e.global::<u32>(0x011f_d428), 0x0038_4000);
        assert_eq!(e.global::<u32>(0x011f_d42c), 0x0038_9800);
    }

    #[test]
    fn fn_00c01c20_keeps_a_pass_held_twice_at_its_count() {
        let mut e = setup_rig(STEPS_00C01C20);
        let first = e.global::<u32>(0x011f_e7a0);
        e.set_global(0x011f_e7a4, first);
        fn_00c01c20(&mut e);
        assert_eq!(e.mem.u32(first + 0x64), 1);
        assert_eq!(states_of(&e, first).len(), 14);
        assert!(calls(&e, PASS_DELETE_00E80190).is_empty());
    }

    #[test]
    fn fn_00be7420_leaves_the_stages_of_a_pass_that_has_them() {
        let mut e = setup_rig(STEPS_00BE7420);
        let first = e.global::<u32>(0x011f_e1e8);
        let second = e.global::<u32>(0x011f_e1ec);
        e.mem.set_u32(first + 0x18, 4);
        fn_00be7420(&mut e);
        let set = calls(&e, PASS_SET_STAGE);
        assert_eq!(set.len(), 4);
        assert!(set.iter().all(|a| a[0] == second));
        // Stages 1 to 3 take their texture word +8 from the globals.
        let stage = set[1][2];
        assert_eq!(e.mem.u32(stage + 8), e.global::<u32>(0x011f_9534));
        let setups = calls(&e, SETUP_DEFAULT_STAGE);
        assert_eq!(setups[3][1..].to_vec(), vec![3, 1, 2, 1]);
    }

    #[test]
    fn fn_00bfc860_gives_the_loop_stages_their_indices() {
        let mut e = setup_rig(STEPS_00BFC860);
        fn_00bfc860(&mut e);
        let setups = calls(&e, SETUP_DEFAULT_STAGE);
        let indices: Vec<u32> = setups.iter().map(|a| a[1]).collect();
        let run: Vec<u32> = (0..0xe).collect();
        assert!(indices.windows(0xe).any(|w| w == run.as_slice()));
        let long: Vec<u32> = (0..0x10).collect();
        assert!(indices.windows(0x10).any(|w| w == long.as_slice()));
    }

    #[test]
    fn fn_00bfc860_chooses_the_stage_word_by_the_flag() {
        for (flag, global) in [(1u8, 0x011f_953cu32), (0, 0x011f_9540)] {
            let mut e = setup_rig(STEPS_00BFC860);
            e.set_global(0x011f_953c, 0x0abc_0001u32);
            e.set_global(0x011f_9540, 0x0abc_0002u32);
            e.set_global(0x011a_d80c, flag);
            fn_00bfc860(&mut e);
            let wanted = e.global::<u32>(global);
            let stages: Vec<u32> = calls(&e, PASS_SET_STAGE).iter().map(|a| a[2]).collect();
            let chosen: Vec<u32> = stages
                .iter()
                .filter(|s| e.mem.u32(**s + 8) == wanted)
                .copied()
                .collect();
            assert_eq!(chosen.len(), 1);
            assert_eq!(e.mem.u32(chosen[0] + 0xc), 1);
            assert!(calls(&e, STAGE_CALL_00E7DE90)
                .iter()
                .any(|a| a == &vec![chosen[0], 3]));
        }
    }

    #[test]
    fn fn_00bf0720_filters_and_chooses_by_the_mode_word() {
        for (mode, filter) in [(1u32, 0u32), (2, 0), (3, 1)] {
            let mut e = setup_rig(STEPS_00BF0720);
            e.set_global(0x011f_91b0, mode);
            e.set_global(0x011f_948c, 2u32);
            e.set_global(0x011f_dd68, 0x0abc_0010u32);
            e.set_global(0x011f_dd78, 0x0abc_0020u32);
            fn_00bf0720(&mut e);
            let filters = calls(&e, SET_FILTER_MODE);
            assert_eq!(filters.len(), 3);
            assert!(filters.iter().all(|a| a[1] == filter));
            let chosen = if mode == 3 { 0x0abc_0020 } else { 0x0abc_0010 };
            let pixel = calls(&e, SET_PASS_44_00B80600);
            assert_eq!(pixel.iter().filter(|a| a[1] == chosen).count(), 3);
            // The filtered stage is entry 6 of the held pass's stage array.
            let pass = pixel.iter().find(|a| a[1] == chosen).unwrap()[0];
            let stage = e.mem.u32(e.mem.u32(pass + 0x24) + 0x18);
            assert!(filters.iter().any(|a| a[0] == stage));
        }
    }

    #[test]
    fn fn_00bebd20_switches_through_the_pass_pointer() {
        let mut e = setup_rig(STEPS_00BEBD20);
        fn_00bebd20(&mut e);
        let switches = calls(&e, PASS_POINTER_ASSIGN_00BA53C0);
        assert_eq!(switches.len(), 1);
        assert_eq!(switches[0][1], 0x011f_e044);
        let pass = e.global::<u32>(0x011f_e044);
        assert!(calls(&e, PASS_SET_STAGE).iter().any(|a| a[0] == pass));
    }

    #[test]
    fn fn_00be39e0_gives_up_four_passes() {
        let mut e = setup_rig(STEPS_00BE39E0);
        let cleared: Vec<u32> = [0x011f_e1b0u32, 0x011f_e218, 0x011f_e1dc, 0x011f_e240]
            .iter()
            .map(|g| e.global::<u32>(*g))
            .collect();
        fn_00be39e0(&mut e);
        let deleted: Vec<u32> = calls(&e, PASS_DELETE_00E80190)
            .iter()
            .map(|a| a[0])
            .collect();
        assert_eq!(deleted, cleared);
    }

